dexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789022537336","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15168491,"receipt":"cover-archive-v2-readback.json","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"checkedAt":"2026-11-03T09:26:38.922Z","editionKey":"/books/OL28291418M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987246052,"bound_title":"Koning der Vossen","reviewed_at":"2026-11-03T09:26:38.922+00:00","bound_isbn13":"9789022537336","evidence_url":"https://data.bibliotheken.nl/id/nbt/p26165733X","review_batch":"nl-scale-20261102-047","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987304014}'::jsonb as exact union all select 'catalog_work_descriptions:3' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146024 and t.language='nl')='{"text":"De spanningen tussen de vier kattenclans nemen toe en de voorspelling die drie jonge katten verbindt, is nog niet opgehelderd. Een oproep om hulp uit de bergen biedt mogelijk nieuwe antwoorden. Terwijl één van hen de eigen clan tegen verdere strijd probeert te beschermen, vertrekt een ander naar de stam die daar leeft. Hun zoektocht brengt de geschiedenis van de clans en die van de bergkatten dichter bij elkaar. Tegelijk blijft onzeker of de bekende regels voldoende bescherming bieden tegen de groeiende dreiging.","work_id":987146024,"evidence":[{"note":"Retain existing Work3394 Sign of the Moon / Erin Hunter and exact Dutch Spoor van de maan 9789059245983 hardcover. KB original-title/volume and existing source-edition parent compared; original content review content-review-023.json retained. Translated character names not guessed; series orde