kedAt":"2026-11-03T09:26:38.922Z","editionKey":"/books/OL60455541M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987246037,"bound_title":"Een wereld zonder prinsen","reviewed_at":"2026-11-03T09:26:38.922+00:00","bound_isbn13":"9789402711578","evidence_url":"https://data.bibliotheken.nl/id/nbt/p436692872","review_batch":"nl-scale-20261102-047","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987345009}'::jsonb as exact union all select 'catalog_work_descriptions:7' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146040 and t.language='nl')='{"text":"James Bond onderzoekt een smokkelnetwerk dat diamanten van Afrika via Londen naar de Verenigde Staten brengt. Tiffany Case vormt een schakel tussen hem en de mensen achter de handel. Met haar hulp probeert hij dieper in de organisatie door te dringen. Eenmaal in Amerika wordt zijn positie steeds gevaarlijker en blijkt zijn opdracht niet alleen te draaien om het volgen van kostbare stenen. Bond moet ook bepalen wie hij kan vertrouwen wanneer degenen die hij volgt zelf de jacht op hem openen.","work_id":987146040,"evidence":[{"note":"Retain existing Work3524 Diamonds are Forever / Ian Fleming and exact Dutch Doden Voor Diamanten 9789044904628 paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-023.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p085878472","http://data.bibliotheken.nl/id/nbt/p833323954","http://data.bibliotheken.nl/id/nbt/p864591039"],"reference":"work:3524","checked_at":"2026-11-03T09:26:38.922Z","can