ified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987246021,"bound_title":"Legendes & Lattes","reviewed_at":"2026-11-03T09:26:38.922+00:00","bound_isbn13":"9789020555523","evidence_url":"https://data.bibliotheken.nl/id/nbt/p440511844","review_batch":"nl-scale-20261102-047","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987346010}'::jsonb as exact union all select 'catalog_work_descriptions:11' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146007 and t.language='nl')='{"text":"Een voorspelling geeft aan dat drie nakomelingen van Vuurster bijzondere macht zullen dragen. Eén van de jonge katten probeert te ontdekken wat die woorden betekenen en denkt dat antwoorden bij de oude geschiedenis van de clans liggen. Zijn zoektocht richt zich op de bergen, waar een andere stam leeft. Ook zijn twee verwanten voelen zich om eigen redenen tot die reis aangetrokken. Wat zij zoeken, blijkt verbonden met geheimen die niet alleen hun eigen toekomst, maar ook hun band met het verleden raken.","work_id":987146007,"evidence":[{"note":"Retain existing Work3010 Outcast / Erin Hunter and exact Dutch Verbannen 9789059245570 paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-023.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p420970088"],"reference":"work:3010","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-023.json","sources":["https://openlibrary.org/works/OL5714309W","https://data.bibliotheken.nl/id/nbt/p4