ng Work3260 Ordinary Men / Christopher R. Browning and exact Dutch Doodgewone mannen 9789401917223 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-023.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p427681472"],"reference":"work:3260","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-023.json","sources":["https://openlibrary.org/works/OL85351W","https://data.bibliotheken.nl/id/nbt/p427681472"]},{"note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789401917223","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15105102,"receipt":"cover-archive-v2-readback.json","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"checkedAt":"2026-11-03T09:26:38.922Z","editionKey":"/books/OL59621995M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL85351W","reviewed_at":"2026-11-03T09:26:38.922+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-047","review_status":"approved","bound_author_id":987346007}'::jsonb as exact union all select 'catalog_edition_metadata:14' as ref,(select to_jsonb(t) from public.catalog_e