hor_id":987346007}'::jsonb as exact union all select 'catalog_work_descriptions:15' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146016 and t.language='nl')='{"text":"Sloane en Rowan leren elkaar kennen als rivalen die allebei moorden plegen. Hun onverwachte verstandhouding groeit uit tot een terugkerende wedstrijd waarin zij gevaarlijke tegenstanders opzoeken. Gaandeweg verandert de vriendschap ook in een romantische verhouding. Die toenadering maakt de gevolgen van hun eerdere daden niet ongedaan. De roman combineert hun wisselende perspectieven met de vraag of een band standhoudt binnen het gewelddadige spel dat zij zelf hebben georganiseerd. Het is het eerste afzonderlijk leesbare deel van Ruinous Love.","work_id":987146016,"evidence":[{"note":"Retain existing Work3321 Butcher & Blackbird / Brynne Weaver and exact Dutch Butcher & Blackbird 9789464405262 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-023.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p442926790"],"reference":"work:3321","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-023.json","sources":["https://openlibrary.org/works/OL36775731W","https://data.bibliotheken.nl/id/nbt/p442926790"]},{"note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789464405262","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","cove